import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"设置声音与语音","description":"","frontmatter":{"title":"设置声音与语音","docId":"user.plugins.audio","translationKey":"user.plugins.audio","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"e0e5014682213e36dda2e4c02293b8f960f3c107bdb1679327fb00b92e02604b","translationRevision":"56613ba24ddf31fc0a99f140b6a4451097169261713afd71976c0d293c416c19","order":20},"headers":[],"relativePath":"zh/user/plugins/audio.md","filePath":"zh/user/plugins/audio.md","lastUpdated":1795731074000}`),a={name:`zh/user/plugins/audio.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="set-up-sounds-and-speech" tabindex="-1">设置声音与语音 <a class="header-anchor" href="#set-up-sounds-and-speech" aria-label="Permalink to “设置声音与语音”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目标与前置条件”">​</a></h2><p>先验证可预测的声音播放，再把音频关联到繁忙的直播活动。你需要正常的输出设备和现有且受支持的音频文件。本地 <strong>播放声音</strong>（<code>audio.play</code>）是内置操作；已安装的 SonicBoom 集成等语音提供商需要单独配置插件或服务。</p><h2 id="test-a-local-sound" tabindex="-1">测试本地声音 <a class="header-anchor" href="#test-a-local-sound" aria-label="Permalink to “测试本地声音”">​</a></h2><ol><li>在 <strong>自动化 → 操作</strong> 中创建 <strong>播放声音</strong>（<code>audio.play</code>）。使用媒体选择器选择已有文件。</li><li>首次检查将音量设为 <code>0.2</code>。支持范围为 <code>0</code> 到 <code>1</code>，零表示静音。</li><li>选择重叠策略：<code>allow</code> 允许同时播放，<code>restart</code> 重新开始播放，<code>drop</code> 在当前声音播放时忽略新的实例。</li><li>保存操作，并在选择 <strong>运行测试</strong> 前阅读配置。此测试可能播放可听见的声音。</li><li>通过预期设备试听。本地播放成功后，将操作关联到带有保守<a href="./../automations/recipes.html">筛选与冷却</a>的事件。</li></ol><p>该操作保留基于路径的媒体引用。TikTools 不会将音频文件复制到数据库。请将文件保留在该路径，并在迁移或备份环境时单独包含它。</p><h2 id="configure-optional-speech" tabindex="-1">配置可选语音 <a class="header-anchor" href="#configure-optional-speech" aria-label="Permalink to “配置可选语音”">​</a></h2><p>通过<a href="./">插件</a>安装可信的语音插件。在其连接或设置控件中，验证服务地址、身份验证、所选提供商、语言及声音/配置。测试简短且不敏感的句子前，先加载声音目录。缺少声音时，应排查目录、所有权或提供商是否不匹配，不要编造标识符来替代。</p><p>对 SonicBoom 而言，合成、获准播放及可听播放完成是不同结果。已排队或已开始的响应不能证明有人听到了句子。克隆语音可能慢于聊天到达速度，因此请查看队列或饱和诊断，并限制事件准入数量。</p><h2 id="expected-result-status-and-recovery" tabindex="-1">预期结果、状态与恢复 <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to “预期结果、状态与恢复”">​</a></h2><p>宿主声明支持音频时，可使用本地播放。语音仍依赖已安装插件和可访问服务；这里不保证提供商、设备或平台已通过验收。无声时，检查文件是否存在、音量、输出设备、暂停状态及运行错误。语音失败时，先检查服务和声音目录再重试。直播期间避免反复测试效果；使用<a href="./../preferences/troubleshooting.html">诊断</a>时不要分享令牌或朗读的私密文本。</p><h2 id="command-line-operations" tabindex="-1">命令行操作 <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “命令行操作”">​</a></h2><p>本指南中的每个操作也可通过 CLI 使用——离线、可编写脚本、适合代理。用法行是解析器语法,在所有语言中保持英文。</p><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools media validate &lt;path&gt; [--kind audio&amp;#124;video&amp;#124;image&amp;#124;other]</code></td><td>在动作中使用前验证媒体文件</td></tr></tbody></table><p>查看<a href="./../../developer/cli.html">完整命令参考</a>了解约定、JSON 输出和破坏性操作标记。</p>`,15)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};